    lyrics:[{label:"Berklee: prosody in music and songwriting",url:"https://online.berklee.edu/takenote/prosody-in-music-and-songwriting/"}],
    theory:[{label:"Open Music Theory",url:"https://human.libretexts.org/Bookshelves/Music/Music_Theory/Open_Music_Theory_2e_(Gotham_et_al.)"},{label:"Musicca: free music theory lessons",url:"https://www.musicca.com/lessons"}],
    "ear-training":[{label:"Teoria: free ear-training exercises",url:"https://www.teoria.com/en/exercises/"},{label:"Berklee: ear-training exercises",url:"https://online.berklee.edu/takenote/ear-training-exercises-to-help-you-become-a-better-musician/"}],
    arranging:[{label:"Open Music Theory: form and orchestration",url:"https://human.libretexts.org/Bookshelves/Music/Music_Theory/Open_Music_Theory_2e_(Gotham_et_al.)"},{label:"Berklee: arranging concepts",url:"https://online.berklee.edu/takenote/orchestration-how-to-write-for-an-orchestra/"}],
    recording:[{label:"Shure: microphone techniques for recording",url:"https://www.shure.com/en-US/docs/education/Microphone-Techniques-for-Recording"}],
