    sampling:[{label:"Ableton: perspectives on sampling",url:"https://www.ableton.com/en/blog/loop-5-perspectives-on-sampling/"},{label:"Library of Congress: public-domain National Jukebox recordings",url:"https://citizen-dj.labs.loc.gov/loc-jukebox-jazz/use/"}],
