    history:[{label:"Smithsonian: jazz oral histories",url:"https://americanhistory.si.edu/explore/projects/smithsonian-jazz/collections-and-archives/smithsonian-jazz-oral-history-program"},{label:"Library of Congress: recorded sound collections",url:"https://www.loc.gov/audio/collections"}],
